def get_transactions_by_address(chain_id, address, age_from=None, age_to=None, methods=None, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0030000" if __import__("os").path.isdir("./environment_mix/0030000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str): return dt
        if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 string or null")
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 timestamp")
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc), None

    def _norm_addr(a):
        if not isinstance(a, str): return None
        s = a.strip().lower()
        if not re.fullmatch(r"0x[0-9a-f]{40}", s or ""):
            return None
        return s

    def _norm_method(m):
        if m is None: return None
        if not isinstance(m, str): return "__INVALID__"
        s = m.strip().lower()
        if not re.fullmatch(r"0x[0-9a-f]{8}", s or ""):
            return "__INVALID__"
        return s

    def _new_id(prefix):
        import secrets
        ts = datetime.datetime.now(datetime.timezone.utc).strftime("%y%m%d%H%M%S")
        return f"{prefix}_{ts}{secrets.token_hex(8)}"

    def _cache_key(tool_name, chain_id_val, normalized_params):
        canon = json.dumps(
            {"tool_name": tool_name, "chain_id": chain_id_val, "normalized_params": normalized_params},
            sort_keys=True, separators=(",", ":"), ensure_ascii=False
        )
        return hashlib.sha256(canon.encode("utf-8")).hexdigest()

    sessions = _load("mcp_sessions.json")
    chains = _load("chains.json")
    tool_requests = _load("tool_requests.json")
    response_cache = _load("response_cache.json")

    # Ambient session
    session = next((s for s in sessions if isinstance(s, dict) and s.get("status") in ("initialized", "closed", "expired") and isinstance(s.get("id"), str)), None)
    if session is None:
        session = next((s for s in sessions if isinstance(s, dict) and s.get("status") == "new" and isinstance(s.get("id"), str)), None)
    if session is None:
        return _err("UNAUTHORIZED", "No MCP session context available to serve this request")

    # Validate base types
    if not isinstance(chain_id, str) or not chain_id.strip():
        return _err("VALIDATION_ERROR", "chain_id must be a non-empty string")
    n_chain_id = chain_id.strip()

    n_addr = _norm_addr(address)
    if n_addr is None:
        return _err("VALIDATION_ERROR", "address must be lowercase 0x-prefixed hex (20 bytes)", error_code="INVALID_ADDRESS")

    dt_from, e = _parse_rfc3339(age_from, "age_from")
    if e: return e
    dt_to, e = _parse_rfc3339(age_to, "age_to")
    if e: return e

    if dt_from is not None and dt_to is not None and dt_from > dt_to:
        return _err("VALIDATION_ERROR", "age_from must be <= age_to", error_code="INVALID_TIME_RANGE")

    n_methods = _norm_method(methods)
    if n_methods == "__INVALID__":
        return _err("VALIDATION_ERROR", "methods must be a 4-byte selector like 0x304e6ade", error_code="INVALID_METHOD")

    # Record request received
    req_id = _new_id("bcs_req")
    req_row = {
        "id": req_id,
        "session_id": session["id"],
        "tool_name": "get_transactions_by_address",
        "chain_id": n_chain_id,
        "address": n_addr,
        "transaction_hash": None,
        "number_or_hash": None,
        "ens_name": None,
        "symbol_query": None,
        "token_address": None,
        "age_from": _iso(dt_from) if dt_from else None,
        "age_to": _iso(dt_to) if dt_to else None,
        "methods": n_methods,
        "include_transactions": None,
        "include_raw_input": None,
        "cursor": None,
        "status": "received",
        "error_code": None,
        "error_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    tool_requests.append(req_row)

    # Session must be initialized
    if session.get("status") == "new":
        req_row["status"] = "rejected"
        req_row["error_code"] = "NOT_INITIALIZED"
        req_row["error_message"] = "session must call __get_instructions__ before invoking tools"
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("tool_requests.json", tool_requests)
        return _err("UNAUTHORIZED", "Session not initialized", request_id=req_id, error_code="NOT_INITIALIZED")

    # Chain routing validation
    chain_row = next((c for c in chains if isinstance(c, dict) and c.get("chain_id") == n_chain_id), None)
    if chain_row is None:
        req_row["status"] = "rejected"
        req_row["error_code"] = "INVALID_CHAIN"
        req_row["error_message"] = "chain_id not found"
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("tool_requests.json", tool_requests)
        return _err("NOT_FOUND", "Unknown chain_id", chain_id=n_chain_id, request_id=req_id)
    if chain_row.get("status") == "disabled":
        req_row["status"] = "rejected"
        req_row["error_code"] = "CHAIN_DISABLED"
        req_row["error_message"] = "chain is disabled"
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("tool_requests.json", tool_requests)
        return _err("CONFLICT", "Chain is disabled", chain_id=n_chain_id, request_id=req_id, error_code="CHAIN_DISABLED")

    req_row["status"] = "validated"
    req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))

    normalized_params = {
        "address": n_addr,
        "age_from": _iso(dt_from) if dt_from else None,
        "age_to": _iso(dt_to) if dt_to else None,
        "methods": n_methods,
    }
    ck = _cache_key("get_transactions_by_address", n_chain_id, normalized_params)

    # Cache hit
    now2 = datetime.datetime.now(datetime.timezone.utc)
    cache_hit = None
    for c in response_cache:
        if not isinstance(c, dict): 
            continue
        if c.get("cache_key") != ck: 
            continue
        if c.get("tool_name") != "get_transactions_by_address":
            continue
        if c.get("status") != "fresh":
            continue
        exp = c.get("expires_at")
        try:
            exp_dt = datetime.datetime.fromisoformat(exp.replace("Z", "+00:00")) if isinstance(exp, str) else None
        except Exception:
            exp_dt = None
        if exp_dt is not None and exp_dt > now2:
            cache_hit = c
            break

    if cache_hit is not None:
        req_row["status"] = "served_from_cache"
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        req_row["status"] = "succeeded"
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("tool_requests.json", tool_requests)
        latency_ms = int((time.time() - t0) * 1000)
        payload = cache_hit.get("payload")
        # Normal envelope for list endpoints
        if isinstance(payload, dict) and "items" in payload:
            return {"chain_id": n_chain_id, "address": n_addr, **payload, "served_from_cache": True, "request_id": req_id, "latency_ms": latency_ms}
        return {"chain_id": n_chain_id, "address": n_addr, "items": payload if isinstance(payload, list) else [], "total": len(payload) if isinstance(payload, list) else 0, "has_more": False, "next_cursor": None, "served_from_cache": True, "request_id": req_id, "latency_ms": latency_ms}

    # Offline: serve from historical succeeded tool_requests by returning matching request records as "items"
    # This keeps behavior data-backed without fabricating upstream tx rows.
    hist = []
    for tr in tool_requests:
        if not isinstance(tr, dict): 
            continue
        if tr.get("tool_name") != "get_transactions_by_address":
            continue
        if tr.get("status") != "succeeded":
            continue
        if tr.get("chain_id") != n_chain_id:
            continue
        if (tr.get("address") or "").lower() != n_addr:
            continue
        # time-window filter
        try:
            tr_from = datetime.datetime.fromisoformat(tr["age_from"].replace("Z", "+00:00")) if tr.get("age_from") else None
        except Exception:
            tr_from = None
        try:
            tr_to = datetime.datetime.fromisoformat(tr["age_to"].replace("Z", "+00:00")) if tr.get("age_to") else None
        except Exception:
            tr_to = None
        if dt_from and tr_to and tr_to < dt_from:
            continue
        if dt_to and tr_from and tr_from > dt_to:
            continue
        if n_methods and tr.get("methods") and tr.get("methods") != n_methods:
            continue
        hist.append({
            "request_id": tr.get("id"),
            "age_from": tr.get("age_from"),
            "age_to": tr.get("age_to"),
            "methods": tr.get("methods"),
            "status": tr.get("status"),
        })

    payload = {"items": hist, "total": len(hist), "has_more": False, "next_cursor": None}
    # Write-through cache for a short time
    created = datetime.datetime.now(datetime.timezone.utc)
    expires = created + datetime.timedelta(minutes=2)
    payload_bytes = len(json.dumps(payload, ensure_ascii=False, separators=(",", ":"), sort_keys=True).encode("utf-8"))
    existing = next((c for c in response_cache if isinstance(c, dict) and c.get("cache_key") == ck), None)
    if existing is None:
        response_cache.append({
            "id": _new_id("bcs_cache"),
            "cache_key": ck,
            "tool_name": "get_transactions_by_address",
            "chain_id": n_chain_id,
            "normalized_params": normalized_params,
            "payload": payload,
            "payload_bytes": payload_bytes,
            "etag": None,
            "expires_at": _iso(expires),
            "status": "fresh",
            "created_at": _iso(created),
            "updated_at": _iso(created),
        })
    else:
        existing["tool_name"] = "get_transactions_by_address"
        existing["chain_id"] = n_chain_id
        existing["normalized_params"] = normalized_params
        existing["payload"] = payload
        existing["payload_bytes"] = int(payload_bytes)
        existing["expires_at"] = _iso(expires)
        if existing.get("status") in ("fresh", "stale"):
            existing["status"] = "fresh"
        existing["updated_at"] = _iso(created)

    req_row["status"] = "succeeded"
    req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _save("response_cache.json", response_cache)
    _save("tool_requests.json", tool_requests)

    return {"chain_id": n_chain_id, "address": n_addr, **payload, "served_from_cache": False, "request_id": req_id, "latency_ms": int((time.time() - t0) * 1000)}

