        if cur is None:
            return 0, None
        if not isinstance(cur, str) or not cur:
            return None, _err("VALIDATION_ERROR", "cursor must be a string or null")
        try:
            raw = base64.b64decode(cur.encode("utf-8"), validate=False).decode("utf-8", "replace")
            obj = json.loads(raw)
            off = obj.get("offset", 0)
            if not isinstance(off, int) or off < 0:
                return None, _err("VALIDATION_ERROR", "cursor is invalid")
            return off, None
        except Exception:
            return None, _err("VALIDATION_ERROR", "cursor is invalid")

    def _encode_cursor(offset):
        blob = json.dumps({"offset": int(offset)}, separators=(",", ":"), sort_keys=True).encode("utf-8")
        return base64.b64encode(blob).decode("utf-8")

