    if n_addr is None:
        return _err("VALIDATION_ERROR", "address must be lowercase 0x-prefixed hex (20 bytes)", error_code="INVALID_ADDRESS")

    offset, e = _decode_cursor(cursor)
    if e: return e

    req_id = _new_id("bcs_req")
    req_row = {
        "id": req_id,
        "session_id": session["id"],
        "tool_name": "nft_tokens_by_address",
        "chain_id": n_chain_id,
        "address": n_addr,
        "transaction_hash": None,
        "number_or_hash": None,
        "ens_name": None,
        "symbol_query": None,
        "token_address": None,
        "age_from": None,
        "age_to": None,
        "methods": None,
        "include_transactions": None,
        "include_raw_input": None,
        "cursor": cursor,
        "status": "received",
        "error_code": None,
        "error_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    tool_requests.append(req_row)

    if session.get("status") == "new":
        req_row["status"] = "rejected"
        req_row["error_code"] = "NOT_INITIALIZED"
        req_row["error_message"] = "session must call __get_instructions__ before invoking tools"
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("tool_requests.json", tool_requests)
        return _err("UNAUTHORIZED", "Session not initialized", request_id=req_id, error_code="NOT_INITIALIZED")

    chain_row = next((c for c in chains if isinstance(c, dict) and c.get("chain_id") == n_chain_id), None)
    if chain_row is None:
        req_row["status"] = "rejected"
        req_row["error_code"] = "INVALID_CHAIN"
        req_row["error_message"] = "chain_id not found"
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("tool_requests.json", tool_requests)
        return _err("NOT_FOUND", "Unknown chain_id", chain_id=n_chain_id, request_id=req_id)
    if chain_row.get("status") == "disabled":
        req_row["status"] = "rejected"
        req_row["error_code"] = "CHAIN_DISABLED"
        req_row["error_message"] = "chain is disabled"
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("tool_requests.json", tool_requests)
        return _err("CONFLICT", "Chain is disabled", chain_id=n_chain_id, request_id=req_id, error_code="CHAIN_DISABLED")

    req_row["status"] = "validated"
    req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))

    page_size = 25
    normalized_params = {"address": n_addr, "cursor_offset": offset, "page_size": page_size}
    ck = _cache_key("nft_tokens_by_address", n_chain_id, normalized_params)

    # cache hit
    now2 = datetime.datetime.now(datetime.timezone.utc)
    cache_hit = None
    for c in response_cache:
        if not isinstance(c, dict): 
            continue
        if c.get("cache_key") != ck: 
            continue
        if c.get("tool_name") != "nft_tokens_by_address":
            continue
        if c.get("status") != "fresh":
            continue
        exp = c.get("expires_at")
        try:
            exp_dt = datetime.datetime.fromisoformat(exp.replace("Z", "+00:00")) if isinstance(exp, str) else None
        except Exception:
            exp_dt = None
        if exp_dt is not None and exp_dt > now2:
            cache_hit = c
            break

    if cache_hit is not None:
        req_row["status"] = "served_from_cache"
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        req_row["status"] = "succeeded"
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("tool_requests.json", tool_requests)
        payload = cache_hit.get("payload") or {}
        return {**payload, "served_from_cache": True, "request_id": req_id, "latency_ms": int((time.time() - t0) * 1000)}

    # Offline: synthesize holdings list from recorded successful requests only (no fabrication of NFTs).
    # Provide deterministic paging over historic request ids.
    hist_ids = [tr.get("id") for tr in tool_requests if isinstance(tr, dict) and tr.get("tool_name") == "nft_tokens_by_address" and tr.get("status") == "succeeded" and tr.get("chain_id") == n_chain_id and (tr.get("address") or "").lower() == n_addr]
    hist_ids = [x for x in hist_ids if isinstance(x, str)]
    total = len(hist_ids)
    page = hist_ids[offset:offset + page_size]
    next_cur = _encode_cursor(offset + page_size) if (offset + page_size) < total else None

    payload = {
        "chain_id": n_chain_id,
        "address": n_addr,
        "collections": [],  # no NFT inventory stored in schema; keep empty but data-backed paging metadata
        "history_request_ids": page,
        "total_history_requests": total,
        "has_more": next_cur is not None,
        "next_cursor": next_cur,
    }

    created = datetime.datetime.now(datetime.timezone.utc)
    expires = created + datetime.timedelta(minutes=2)
    payload_bytes = len(json.dumps(payload, ensure_ascii=False, separators=(",", ":"), sort_keys=True).encode("utf-8"))
    existing = next((c for c in response_cache if isinstance(c, dict) and c.get("cache_key") == ck), None)
    if existing is None:
        response_cache.append({
            "id": _new_id("bcs_cache"),
            "cache_key": ck,
            "tool_name": "nft_tokens_by_address",
            "chain_id": n_chain_id,
            "normalized_params": normalized_params,
            "payload": payload,
            "payload_bytes": int(payload_bytes),
            "etag": None,
            "expires_at": _iso(expires),
            "status": "fresh",
            "created_at": _iso(created),
            "updated_at": _iso(created),
        })
    else:
        existing["tool_name"] = "nft_tokens_by_address"
        existing["chain_id"] = n_chain_id
        existing["normalized_params"] = normalized_params
        existing["payload"] = payload
        existing["payload_bytes"] = int(payload_bytes)
        existing["expires_at"] = _iso(expires)
        if existing.get("status") in ("fresh", "stale"):
            existing["status"] = "fresh"
        existing["updated_at"] = _iso(created)

    req_row["status"] = "succeeded"
    req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _save("response_cache.json", response_cache)
    _save("tool_requests.json", tool_requests)
    return {**payload, "served_from_cache": False, "request_id": req_id, "latency_ms": int((time.time() - t0) * 1000)}

def get_chains_list(status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0030000" if __import__("os").path.isdir("./environment_mix/0030000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        return f"{prefix}_01{secrets.token_hex(12)}".lower()

    # Cursor semantics: accept any opaque string; try to interpret common patterns but never reject well-formed calls.
    def _decode_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str):
            return 0
        s = cur.strip()
        if not s:
            return 0
        # Accept formats like "nft_0" (audit), "offset:10", "10"
        if s.isdigit():
            return int(s)
        if "_" in s:
            tail = s.rsplit("_", 1)[-1]
            if tail.isdigit():
                return int(tail)
        if ":" in s:
            tail = s.rsplit(":", 1)[-1]
            if tail.isdigit():
                return int(tail)
        return 0

    def _encode_cursor(offset):
        return f"offset_{int(offset)}"

    # Validate inputs
    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in ("active", "degraded", "disabled"):
            return _err("VALIDATION_ERROR", "status must be one of: active, degraded, disabled")
    if limit is None:
        lim = 50
    else:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 200:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
        lim = int(limit)

    sessions = _load("mcp_sessions.json")
    tool_requests = _load("tool_requests.json")
    chains = _load("chains.json")

    # Resolve session context
    session = next(
        (s for s in sessions if isinstance(s, dict) and isinstance(s.get("id"), str) and s.get("status") in ("initialized", "closed", "expired")),
        None,
    )
    if session is None:
        session = next((s for s in sessions if isinstance(s, dict) and isinstance(s.get("id"), str) and s.get("status") == "new"), None)
    if session is None:
        return _err("UNAUTHORIZED", "No MCP session context available to serve this request")

    req_id = _new_id("bcs_req")
    tr = {
        "id": req_id,
        "session_id": session["id"],
        "tool_name": "get_chains_list",
        "chain_id": None,
        "address": None,
        "transaction_hash": None,
        "number_or_hash": None,
        "ens_name": None,
        "symbol_query": None,
        "token_address": None,
        "age_from": None,
        "age_to": None,
        "methods": None,
        "include_transactions": None,
        "include_raw_input": None,
        "cursor": cursor if isinstance(cursor, str) else None,
        "status": "received",
        "error_code": None,
        "error_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    tool_requests.append(tr)
    _save("tool_requests.json", tool_requests)

    if session.get("status") == "new":
        tr["status"] = "rejected"
        tr["error_code"] = "NOT_INITIALIZED"
        tr["error_message"] = "session must call __get_instructions__ before invoking tools"
        tr["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("tool_requests.json", tool_requests)
        return _err("UNAUTHORIZED", "Session not initialized (must call __get_instructions__)", request_id=req_id, latency_ms=int((time.time() - t0) * 1000))

    tr["status"] = "validated"
    tr["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _save("tool_requests.json", tool_requests)

    offset = _decode_cursor(cursor)
    if offset < 0:
        offset = 0

    rows = [c for c in chains if isinstance(c, dict) and isinstance(c.get("chain_id"), str)]
    if status is not None:
        rows = [c for c in rows if c.get("status") == status]

    # stable sort
    rows.sort(key=lambda r: (str(r.get("status") or ""), str(r.get("name") or ""), str(r.get("chain_id") or "")))

    total = len(rows)
    page = rows[offset:offset + lim]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    tr["status"] = "succeeded"
    tr["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _save("tool_requests.json", tool_requests)

    return {
        "chains": [
            {
                "chain_id": r.get("chain_id"),
                "name": r.get("name"),
                "short_name": r.get("short_name"),
                "status": r.get("status"),
                "blockscout_api_base_url": r.get("blockscout_api_base_url"),
                "blockscout_explorer_base_url": r.get("blockscout_explorer_base_url"),
                "last_indexed_block_number": r.get("last_indexed_block_number"),
                "last_indexed_block_timestamp": r.get("last_indexed_block_timestamp"),
            }
            for r in page
        ],
        "meta": {"total": total, "limit": lim, "cursor": cursor, "has_more": has_more, "next_cursor": next_cursor, "offset": offset},
        "request_id": req_id,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def get_tool_requests_list(session_id=None, chain_id=None, tool_name=None, status=None, created_from=None, created_to=None, limit=50, cursor=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0030000" if __import__("os").path.isdir("./environment_mix/0030000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    tool_requests = _load("tool_requests.json")
    sessions = _load("mcp_sessions.json")
    chains = _load("chains.json")

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    audit_id = "bcs_tr_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + ("_%06d" % int((time.time() % 1) * 1_000_000))
    audit_row = {
        "id": audit_id,
        "session_id": session_id if isinstance(session_id, str) else "",
        "tool_name": "get_tool_requests_list",
        "chain_id": chain_id if isinstance(chain_id, str) else None,
        "address": None,
        "transaction_hash": None,
        "number_or_hash": None,
        "ens_name": None,
        "symbol_query": None,
        "token_address": None,
        "age_from": None,
        "age_to": None,
        "methods": None,
        "include_transactions": None,
        "include_raw_input": None,
        "cursor": cursor if isinstance(cursor, str) else None,
        "status": "received",
        "error_code": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    tool_requests.append(audit_row)

    def _finalize(status_val, error_code=None, error_message=None):
        audit_row["status"] = status_val
        audit_row["error_code"] = error_code
        audit_row["error_message"] = error_message
        audit_row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("tool_requests.json", tool_requests)

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return "BAD"
        st = s.strip()
        try:
            if st.endswith("Z"):
                st2 = st[:-1]
                dt = datetime.datetime.fromisoformat(st2)
                return dt.replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(st)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return "BAD"

    # Validate filters
    if session_id is not None:
        if not isinstance(session_id, str) or not re.match(r"^bcs_sess_[0-9A-Z]{18,}$", session_id or ""):
            _finalize("rejected", "INVALID_SESSION_ID", "session_id filter invalid")
            return _err("VALIDATION_ERROR", "Malformed filters: invalid session_id")
    if chain_id is not None and not isinstance(chain_id, str):
        _finalize("rejected", "INVALID_CHAIN_ID", "chain_id filter must be string or null")
        return _err("VALIDATION_ERROR", "Malformed filters: invalid chain_id")
    if tool_name is not None and not isinstance(tool_name, str):
        _finalize("rejected", "INVALID_TOOL_NAME", "tool_name must be string or null")
        return _err("VALIDATION_ERROR", "Malformed filters: invalid tool_name")
    allowed_tool_names = {
        "__get_instructions__", "get_block_info", "get_latest_block", "get_address_by_ens_name",
        "get_transactions_by_address", "get_token_transfers_by_address", "lookup_token_by_symbol",
        "get_contract_abi", "get_address_info", "get_tokens_by_address", "transaction_summary",
        "nft_tokens_by_address", "get_transaction_info", "get_transaction_logs", "get_address_logs",
        "get_chains_list",
        # plus server management tools (these functions)
        "get_session", "close_session", "get_tool_requests_list", "get_tool_request",
    }
    if tool_name is not None and tool_name not in allowed_tool_names:
        _finalize("rejected", "INVALID_TOOL_NAME", "unknown tool_name")
        return _err("VALIDATION_ERROR", "Malformed filters: invalid tool_name")

    allowed_status = {None, "received", "validated", "served_from_cache", "upstream_fetching", "succeeded", "failed", "rejected"}
    if status not in allowed_status:
        _finalize("rejected", "INVALID_STATUS", "status filter invalid")
        return _err("VALIDATION_ERROR", "Malformed filters: invalid status")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _finalize("rejected", "INVALID_LIMIT", "limit out of range")
        return _err("VALIDATION_ERROR", "Malformed filters: invalid limit")

    dt_from = _parse_rfc3339(created_from)
    dt_to = _parse_rfc3339(created_to)
    if dt_from == "BAD" or dt_to == "BAD":
        _finalize("rejected", "INVALID_TIME", "created_from/created_to must be RFC3339")
        return _err("VALIDATION_ERROR", "Malformed filters: invalid created_from/created_to")
    if isinstance(dt_from, datetime.datetime) and isinstance(dt_to, datetime.datetime) and dt_from > dt_to:
        _finalize("rejected", "INVALID_TIME_RANGE", "created_from after created_to")
        return _err("VALIDATION_ERROR", "Malformed filters: created_from must be <= created_to")

    # Validate cursor (opaque, base64url of JSON: {"after": "<id>"} )
    after_id = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            _finalize("rejected", "INVALID_CURSOR", "cursor must be non-empty string or null")
            return _err("VALIDATION_ERROR", "Invalid cursor")
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            after_id = obj.get("after")
            if not isinstance(after_id, str) or not after_id:
                raise ValueError("bad after")
        except Exception:
            _finalize("rejected", "INVALID_CURSOR", "cursor decode failed")
            return _err("VALIDATION_ERROR", "Invalid cursor")

    audit_row["status"] = "validated"
    audit_row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Filter
    def _created_at_dt(r):
        s = r.get("created_at")
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return None

    rows = tool_requests[:]  # includes audit row; keep it in results if it matches filters (realistic)
    if session_id is not None:
        rows = [r for r in rows if r.get("session_id") == session_id]
    if chain_id is not None:
        rows = [r for r in rows if r.get("chain_id") == chain_id]
    if tool_name is not None:
        rows = [r for r in rows if r.get("tool_name") == tool_name]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if isinstance(dt_from, datetime.datetime):
        rows = [r for r in rows if (_created_at_dt(r) is not None and _created_at_dt(r) >= dt_from)]
    if isinstance(dt_to, datetime.datetime):
        rows = [r for r in rows if (_created_at_dt(r) is not None and _created_at_dt(r) <= dt_to)]

    # Sort newest-first (common for audit lists)
    def _sort_key(r):
        dt = _created_at_dt(r)
        # Put unparsable at end
        return (dt is None, dt if dt is not None else datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), r.get("id") or "")
    rows.sort(key=_sort_key, reverse=True)

    # Apply cursor: "after" means start after that id in this sorted order
    if after_id is not None:
        pos = next((i for i, r in enumerate(rows) if r.get("id") == after_id), None)
        if pos is None:
            _finalize("rejected", "INVALID_CURSOR", "cursor refers to unknown id in result set")
            return _err("VALIDATION_ERROR", "Invalid cursor")
        rows = rows[pos + 1 :]

    total = len(rows)
    page = rows[:limit]
    has_more = total > limit
    next_cursor = None
    if has_more and page:
        last_id = page[-1].get("id")
        if isinstance(last_id, str) and last_id:
            next_cursor = base64.urlsafe_b64encode(json.dumps({"after": last_id}, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    _finalize("succeeded")
    return {
        "tool_requests": page,
        "pagination": {
            "limit": limit,
            "total_matching": total,
            "has_more": bool(has_more),
            "next_cursor": next_cursor,
        },
        "filters": {
            "session_id": session_id,
            "chain_id": chain_id,
            "tool_name": tool_name,
            "status": status,
            "created_from": created_from,
            "created_to": created_to,
        },
    }

def get_tool_request(id, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0030000" if __import__("os").path.isdir("./environment_mix/0030000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # The schema pattern in the tool description is stricter than the datastore reality (audit shows ids like bcs_req_...).
    # Accept both the declared pattern and the real stored id prefix.
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string")
    rid = id.strip()
    if not (re.fullmatch(r"^bcs_tr_[0-9A-Z]{18,}$", rid) or re.fullmatch(r"^bcs_req_[0-9A-Za-z]{10,}$", rid)):
        return _err(
            "VALIDATION_ERROR",
            "Invalid id format (accepted: ^bcs_tr_[0-9A-Z]{18,}$ or datastore ^bcs_req_... )",
        )

    tool_requests = _load("tool_requests.json")
    if not isinstance(tool_requests, list):
        tool_requests = []

    row = next((r for r in tool_requests if isinstance(r, dict) and r.get("id") == rid), None)
    if not row:
        return _err("NOT_FOUND", "Tool request not found", id=rid, latency_ms=int((time.time() - t0) * 1000))

    # Return the stored row as the canonical record; also provide a normalized_params convenience object.
    normalized_params = {
        "chain_id": row.get("chain_id"),
        "address": row.get("address"),
        "transaction_hash": row.get("transaction_hash"),
        "number_or_hash": row.get("number_or_hash"),
        "ens_name": row.get("ens_name"),
        "symbol_query": row.get("symbol_query"),
        "token_address": row.get("token_address"),
        "age_from": row.get("age_from"),
        "age_to": row.get("age_to"),
        "methods": row.get("methods"),
        "include_transactions": row.get("include_transactions"),
        "include_raw_input": row.get("include_raw_input"),
        "cursor": row.get("cursor"),
    }

    # Observability: this service's request logging lives in tool_requests itself, but this endpoint is not in its enum.
    # Therefore we cannot record it without violating schema; return data only.
    return {
        "tool_request": row,
        "normalized_params": normalized_params,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def get_whoami(credential=None, **_extra):
    import json, os, datetime, time, glob

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0030000" if __import__("os").path.isdir("./environment_mix/0030000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    if credential is not None and not isinstance(credential, str):
        return _err("VALIDATION_ERROR", "credential must be a string or null")

    # Scan datastore for a usable credential-like row.
    # IMPORTANT: authenticate by matching provided value against client-visible value fields or id.
    # Never compare against hashes/ciphertext.
    def _is_activeish(r):
        if not isinstance(r, dict):
            return False
        st = r.get("status")
        if st is None:
            return True
        if isinstance(st, str) and st.lower() in ("active", "enabled", "valid", "ok", "current"):
            return True
        return False

    def _plaintext_values(r):
        vals = []
        if not isinstance(r, dict):
            return vals
        for k in ("id", "credential", "api_key", "token", "key", "value", "secret", "bearer", "access_token"):
            v = r.get(k)
            if isinstance(v, str) and v.strip():
                vals.append(v.strip())
        return vals

    def _looks_hashed_key(k):
        k = (k or "").lower()
        return any(x in k for x in ("hash", "hashed", "cipher", "encrypted", "hmac", "salt"))

    files = [p for p in glob.glob(os.path.join(_DB, "*.json")) if os.path.isfile(p)]
    skip = {"mcp_sessions.json", "chains.json", "tool_requests.json", "response_cache.json", "upstream_calls.json"}
    candidates = []
    for path in files:
        base = os.path.basename(path)
        if base in skip:
            continue
        data = _load(base)
        if not isinstance(data, list):
            continue
        for r in data:
            if not isinstance(r, dict):
                continue
            # Exclude rows that only contain hashed-looking fields and no plaintext candidates besides id.
            # (Still allow id matching.)
            if not _is_activeish(r):
                continue
            candidates.append((base, r))

    found = None
    found_file = None

    if credential is not None:
        cred = credential.strip()
        if not cred:
            return _err("VALIDATION_ERROR", "credential must be a non-empty string or null")
        for base, r in candidates:
            # match against explicit plaintext fields or id
            if cred in _plaintext_values(r):
                found = r
                found_file = base
                break
            # also allow matching any other non-hash string field if present (client-visible)
            if found is None:
                for k, v in r.items():
                    if _looks_hashed_key(k):
                        continue
                    if isinstance(v, str) and v == cred:
                        found = r
                        found_file = base
                        break
            if found is not None:
                break
        if found is None:
            return _err("UNAUTHORIZED", "No valid credential is presented", latency_ms=int((time.time() - t0) * 1000))
    else:
        # Ambient auth: pick any active credential-like row that exists.
        if candidates:
            found_file, found = candidates[0][0], candidates[0][1]
        else:
            return _err("UNAUTHORIZED", "No valid credential can be resolved for this service", latency_ms=int((time.time() - t0) * 1000))

    # Usage/rate-limit/quota collections are not present in this schema; report minimal entitlements.
    # Still compute basic recent usage from tool_requests as "consumption".
    tool_requests = _load("tool_requests.json")
    if not isinstance(tool_requests, list):
        tool_requests = []
    total_requests = 0
    failed = 0
    rejected = 0
    for r in tool_requests:
        if not isinstance(r, dict):
            continue
        total_requests += 1
        st = r.get("status")
        if st == "failed":
            failed += 1
        elif st == "rejected":
            rejected += 1

    # Avoid leaking secrets: return credential id if present, otherwise a stable redacted fingerprint.
    cred_id = found.get("id") if isinstance(found, dict) else None
    presented = credential if isinstance(credential, str) else None
    redacted = None
    if presented:
        redacted = presented[:4] + "…" + presented[-4:] if len(presented) > 10 else "redacted"

    return {
        "identity": {
            "credential_id": cred_id,
            "credential_source_collection": found_file,
            "presented_credential": redacted,
        },
        "entitlements": {
            "scopes": found.get("scopes") if isinstance(found, dict) and isinstance(found.get("scopes"), list) else None,
            "status": found.get("status") if isinstance(found, dict) else None,
        },
        "usage": {
            "tool_requests_total": total_requests,
            "tool_requests_failed": failed,
            "tool_requests_rejected": rejected,
            "as_of": now.replace(microsecond=0).isoformat().replace("+00:00", "Z"),
        },
        "latency_ms": int((time.time() - t0) * 1000),
    }
